fn is_ascii_digit(c: char) -> bool {
    // Returns true if c is between '0' and '9' inclusive.
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // For each character in s, check that it is an ASCII digit.
    // The empty string yields true (vacuously).
    for ch in s.chars() {
        if !is_ascii_digit(ch) {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_is_ascii_digit() {
        assert!(is_ascii_digit('0'));
        assert!(is_ascii_digit('5'));
        assert!(is_ascii_digit('9'));
        assert!(!is_ascii_digit('a'));
        assert!(!is_ascii_digit(' '));
        assert!(!is_ascii_digit('Ω')); // Greek capital letter omega
    }

    #[test]
    fn test_all_digits_empty() {
        let s = String::new();
        assert!(all_digits(s));
    }

    #[test]
    fn test_all_digits_mixed() {
        assert!(all_digits("0123456789".to_string()));
        assert!(!all_digits("1234a6789".to_string()));
        assert!(!all_digits("１２３４".to_string())); // full-width digits
        assert!(!all_digits("".to_string() + "7\n8"));
    }

    #[test]
    fn test_all_digits_unicode() {
        assert!(!all_digits("😀123".to_string()));
        assert!(!all_digits("123😀".to_string()));
    }
}